import json
import itertools

def solve():
    houses = [1, 2]

    categories = {
        "Name": ["Arnold", "Eric"],
        "occupation": ["engineer", "doctor"],
        "birthday month": ["april", "sept"],
        "style of house": ["victorian", "colonial"],
        "heights": ["very short", "short"],
        "favorite cigar": ["pall mall", "prince"],
    }

    # Helper to check adjacency
    def are_adjacent(h1, h2):
        return abs(h1 - h2) == 1

    # Check all constraints with partial assignments allowed
    def is_consistent(assignments):
        # Build reverse lookup: for each category, value -> house if assigned
        def house_with(cat, val):
            for h in houses:
                if cat in assignments[h] and assignments[h][cat] == val:
                    return h
            return None

        # Constraint 1: The person who is an engineer is in the first house.
        for h in houses:
            if "occupation" in assignments[h]:
                if assignments[h]["occupation"] == "engineer" and h != 1:
                    return False
        if "occupation" in assignments[1]:
            if assignments[1]["occupation"] != "engineer":
                return False

        # Constraint 2: April and doctor are next to each other.
        h_april = house_with("birthday month", "april")
        h_doctor = house_with("occupation", "doctor")
        if h_april is not None and h_doctor is not None:
            if not are_adjacent(h_april, h_doctor):
                return False

        # Constraint 3: Colonial-style house is the engineer.
        for h in houses:
            if "style of house" in assignments[h] and assignments[h]["style of house"] == "colonial":
                if "occupation" in assignments[h] and assignments[h]["occupation"] != "engineer":
                    return False
            if "occupation" in assignments[h] and assignments[h]["occupation"] == "engineer":
                if "style of house" in assignments[h] and assignments[h]["style of house"] != "colonial":
                    return False

        # Constraint 4: Very short is the engineer.
        for h in houses:
            if "heights" in assignments[h] and assignments[h]["heights"] == "very short":
                if "occupation" in assignments[h] and assignments[h]["occupation"] != "engineer":
                    return False
            if "occupation" in assignments[h] and assignments[h]["occupation"] == "engineer":
                if "heights" in assignments[h] and assignments[h]["heights"] != "very short":
                    return False

        # Constraint 5: Short is Pall Mall.
        for h in houses:
            if "heights" in assignments[h] and assignments[h]["heights"] == "short":
                if "favorite cigar" in assignments[h] and assignments[h]["favorite cigar"] != "pall mall":
                    return False
            if "favorite cigar" in assignments[h] and assignments[h]["favorite cigar"] == "pall mall":
                if "heights" in assignments[h] and assignments[h]["heights"] != "short":
                    return False

        # Constraint 6: The engineer is Eric.
        for h in houses:
            if "occupation" in assignments[h] and assignments[h]["occupation"] == "engineer":
                if "Name" in assignments[h] and assignments[h]["Name"] != "Eric":
                    return False
            if "Name" in assignments[h] and assignments[h]["Name"] == "Eric":
                if "occupation" in assignments[h] and assignments[h]["occupation"] != "engineer":
                    return False

        return True

    # Backtracking over categories
    cat_list = list(categories.keys())

    # Initialize empty assignments per house
    init_assignments = {h: {} for h in houses}

    solution = None

    def backtrack(i, assignments):
        nonlocal solution
        if solution is not None:
            return
        if i == len(cat_list):
            # Full assignment
            if is_consistent(assignments):
                solution = {h: dict(assignments[h]) for h in houses}
            return

        cat = cat_list[i]
        values = categories[cat]

        # Try all permutations of values across houses
        for perm in itertools.permutations(values, len(houses)):
            # Assign this category to all houses
            new_assignments = {h: dict(assignments[h]) for h in houses}
            for idx, h in enumerate(houses):
                new_assignments[h][cat] = perm[idx]

            if is_consistent(new_assignments):
                backtrack(i + 1, new_assignments)
                if solution is not None:
                    return

    backtrack(0, init_assignments)

    if solution is None:
        raise ValueError("No solution found")

    header = ["House", "Name", "occupation", "birthday month", "style of house", "heights", "favorite cigar"]
    rows = []
    for h in houses:
        row = [
            str(h),
            solution[h]["Name"],
            solution[h]["occupation"],
            solution[h]["birthday month"],
            solution[h]["style of house"],
            solution[h]["heights"],
            solution[h]["favorite cigar"],
        ]
        rows.append(row)

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(output, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    solve()
